// desk switches the desktop style preset and light/dark mode at runtime by
// activating home-manager specialisations generated by the desk module.
package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

const usage = `usage: desk <command>

  status                 show applied, selected and default combos
  list                   list available combos
  set <preset> [mode]    apply a preset (mode: dark|light, default: current mode)
  toggle                 flip between dark and light for the current preset
  restore                re-apply the selected combo after login or rebuild`

type paths struct {
	state  string
	data   string
	config string
}

func newPaths() paths {
	home, _ := os.UserHomeDir()
	state := os.Getenv("XDG_STATE_HOME")
	if state == "" {
		state = filepath.Join(home, ".local", "state")
	}
	data := os.Getenv("XDG_DATA_HOME")
	if data == "" {
		data = filepath.Join(home, ".local", "share")
	}
	config := os.Getenv("XDG_CONFIG_HOME")
	if config == "" {
		config = filepath.Join(home, ".config")
	}
	return paths{state: filepath.Join(state, "desk"), data: data, config: config}
}

func (p paths) read(name string) string {
	b, err := os.ReadFile(filepath.Join(p.state, name))
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(b))
}

func (p paths) write(name, value string) error {
	return os.WriteFile(filepath.Join(p.state, name), []byte(value+"\n"), 0o644)
}

func (p paths) combos() ([]string, error) {
	def := p.read("default")
	if def == "" {
		return nil, errors.New("no desk state yet: rebuild with the desk home-manager module first")
	}
	entries, err := os.ReadDir(filepath.Join(p.state, "base", "specialisation"))
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("read specialisations: %w", err)
	}
	combos := []string{def}
	for _, e := range entries {
		combos = append(combos, e.Name())
	}
	sort.Strings(combos)
	return combos, nil
}

func splitCombo(combo string) (preset, mode string) {
	i := strings.LastIndex(combo, "-")
	if i < 0 {
		return combo, ""
	}
	return combo[:i], combo[i+1:]
}

func (p paths) activationFor(combo string) (string, error) {
	base := filepath.Join(p.state, "base")
	if combo == p.read("default") {
		return filepath.Join(base, "activate"), nil
	}
	script := filepath.Join(base, "specialisation", combo, "activate")
	if _, err := os.Stat(script); err != nil {
		return "", fmt.Errorf("unknown combo %q (see `desk list`)", combo)
	}
	return script, nil
}

func run(ctx context.Context, log io.Writer, name string, args ...string) error {
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Stdout, cmd.Stderr = log, log
	return cmd.Run()
}

func notify(summary, body string) {
	_ = exec.Command("notify-send", "--app-name=desk", "--icon=preferences-desktop-theme", summary, body).Run()
}

func (p paths) apply(ctx context.Context, combo string, quiet bool) error {
	script, err := p.activationFor(combo)
	if err != nil {
		return err
	}

	lock, err := os.OpenFile(filepath.Join(p.state, "lock"), os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return fmt.Errorf("open lock: %w", err)
	}
	defer lock.Close()
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		return errors.New("another desk switch is already running")
	}

	logFile, err := os.Create(filepath.Join(p.state, "last.log"))
	if err != nil {
		return fmt.Errorf("create log: %w", err)
	}
	defer logFile.Close()

	if !quiet {
		notify("Changement de style", combo)
	}
	start := time.Now()

	if err := run(ctx, logFile, script); err != nil {
		return fmt.Errorf("activate %s: %w (see %s)", combo, err, logFile.Name())
	}
	// plasma-manager applies themes, panels and wallpapers from login scripts;
	// they are hashed, so only what changed runs again.
	runAll := filepath.Join(p.data, "plasma-manager", "run_all.sh")
	if _, err := os.Stat(runAll); err == nil {
		if err := run(ctx, logFile, runAll); err != nil {
			return fmt.Errorf("plasma-manager scripts: %w (see %s)", err, logFile.Name())
		}
	}
	_ = run(ctx, logFile, "qdbus", "org.kde.KWin", "/KWin", "reconfigure")
	if err := p.ensurePanels(ctx, logFile); err != nil {
		return err
	}

	if err := p.write("selected", combo); err != nil {
		return fmt.Errorf("save selection: %w", err)
	}
	if !quiet {
		notify("Style appliqué", fmt.Sprintf("%s en %.1fs", combo, time.Since(start).Seconds()))
	}
	return nil
}

// ensurePanels replaces the panels when the active generation's layout script
// differs from the last one applied. Wallpapers and desktops are untouched.
func (p paths) ensurePanels(ctx context.Context, log io.Writer) error {
	script, err := os.ReadFile(filepath.Join(p.data, "desk", "panels.js"))
	if err != nil {
		return fmt.Errorf("read panel layout: %w", err)
	}
	sum := sha256.Sum256(script)
	hash := hex.EncodeToString(sum[:])
	if p.read("panels") == hash {
		return nil
	}
	// plasmashell may still be starting after a previous switch restarted it.
	var applyErr error
	for attempt := 0; attempt < 20; attempt++ {
		applyErr = run(ctx, log, "qdbus", "org.kde.plasmashell", "/PlasmaShell", "org.kde.PlasmaShell.evaluateScript", string(script))
		if applyErr == nil {
			break
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(3 * time.Second):
		}
	}
	if applyErr != nil {
		return fmt.Errorf("apply panel layout: %w", applyErr)
	}
	// writeConfig escapes the key; plasmashell only reads the unescaped form.
	appletsrc := filepath.Join(p.config, "plasma-org.kde.plasma.desktop-appletsrc")
	if b, err := os.ReadFile(appletsrc); err == nil {
		fixed := strings.ReplaceAll(string(b), "lastScreen\\x5b$i\\x5d=", "lastScreen[$i]=")
		if err := os.WriteFile(appletsrc, []byte(fixed), 0o600); err != nil {
			return fmt.Errorf("fix panel screens: %w", err)
		}
	}
	if err := run(ctx, log, "systemctl", "--user", "restart", "plasma-plasmashell"); err != nil {
		return fmt.Errorf("restart plasmashell: %w", err)
	}
	return p.write("panels", hash)
}

func main() {
	if err := mainErr(); err != nil {
		fmt.Fprintln(os.Stderr, "desk:", err)
		notify("desk : échec", err.Error())
		os.Exit(1)
	}
}

func mainErr() error {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	p := newPaths()
	if len(os.Args) < 2 {
		fmt.Println(usage)
		return nil
	}

	switch os.Args[1] {
	case "status":
		fmt.Printf("applied:  %s\nselected: %s\ndefault:  %s\n", p.read("applied"), p.read("selected"), p.read("default"))
		return nil

	case "list":
		combos, err := p.combos()
		if err != nil {
			return err
		}
		applied := p.read("applied")
		for _, c := range combos {
			mark := "  "
			if c == applied {
				mark = "* "
			}
			fmt.Println(mark + c)
		}
		return nil

	case "set":
		if len(os.Args) < 3 {
			return errors.New("set needs a preset")
		}
		preset := os.Args[2]
		_, mode := splitCombo(p.read("applied"))
		if len(os.Args) > 3 {
			mode = os.Args[3]
		}
		if strings.Contains(preset, "-") {
			preset, mode = splitCombo(preset)
		}
		if mode != "dark" && mode != "light" {
			return fmt.Errorf("mode must be dark or light, got %q", mode)
		}
		return p.apply(ctx, preset+"-"+mode, false)

	case "toggle":
		preset, mode := splitCombo(p.read("applied"))
		if preset == "" {
			return errors.New("nothing applied yet")
		}
		next := "light"
		if mode == "light" {
			next = "dark"
		}
		return p.apply(ctx, preset+"-"+next, false)

	case "restore":
		selected, applied := p.read("selected"), p.read("applied")
		if selected == "" || selected == applied {
			logFile, err := os.Create(filepath.Join(p.state, "last.log"))
			if err != nil {
				return fmt.Errorf("create log: %w", err)
			}
			defer logFile.Close()
			return p.ensurePanels(ctx, logFile)
		}
		return p.apply(ctx, selected, true)

	default:
		fmt.Println(usage)
		return fmt.Errorf("unknown command %q", os.Args[1])
	}
}
